-- v8 schema before primarySmsRelayEnabled, preserved for migration regression.
CREATE TABLE IF NOT EXISTS `filter_rules` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `senderPattern` TEXT NOT NULL, `matchType` TEXT NOT NULL, `label` TEXT NOT NULL, `keywordFilter` TEXT NOT NULL, `isEnabled` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `forward_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `sender` TEXT NOT NULL, `messageBody` TEXT NOT NULL, `receivedTimestamp` INTEGER NOT NULL, `forwardedTimestamp` INTEGER, `status` TEXT NOT NULL, `httpStatusCode` INTEGER, `responseSummary` TEXT, `errorMessage` TEXT, `matchedRuleLabel` TEXT, `isEncrypted` INTEGER NOT NULL, `payloadPreview` TEXT, `endpointUrl` TEXT NOT NULL, `durationMs` INTEGER NOT NULL, `driverId` TEXT NOT NULL, `smsType` TEXT NOT NULL, `trackingCode` TEXT, `otpCode` TEXT, `signature` TEXT, `retryCount` INTEGER NOT NULL, `lastRetryTimestamp` INTEGER, `simSlot` TEXT NOT NULL, `encryptedBody` TEXT, `recipientPhone` TEXT NOT NULL DEFAULT '', `messageFingerprint` TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS `app_config` (`id` INTEGER NOT NULL, `isMasterEnabled` INTEGER NOT NULL, `endpointUrl` TEXT NOT NULL, `authType` TEXT NOT NULL, `authHeaderKey` TEXT NOT NULL, `authHeaderValue` TEXT NOT NULL, `forwarderSecret` TEXT NOT NULL, `isEncryptionEnabled` INTEGER NOT NULL, `secretEncryptionKey` TEXT NOT NULL, `filterMode` TEXT NOT NULL, `deviceIdentifier` TEXT NOT NULL, `includeMetadata` INTEGER NOT NULL, `showForegroundNotification` INTEGER NOT NULL, `maxRetries` INTEGER NOT NULL, `timeoutSeconds` INTEGER NOT NULL, `enableHealthAlertNotification` INTEGER NOT NULL, `healthCheckIntervalMinutes` INTEGER NOT NULL, `healthFailureThreshold` INTEGER NOT NULL, `notifyOnDisconnect` INTEGER NOT NULL, `enableAutoOfflineSync` INTEGER NOT NULL, `enableCommandPolling` INTEGER NOT NULL, `driverId` TEXT NOT NULL, `driverFullName` TEXT NOT NULL, `driverPhone` TEXT NOT NULL, `autoExtractOtp` INTEGER NOT NULL, `autoExtractTrackingCode` INTEGER NOT NULL, `filterUtcmsOnly` INTEGER NOT NULL, `userConsentGiven` INTEGER NOT NULL, `enableWorkManagerSync` INTEGER NOT NULL, `enableSmsFallback` INTEGER NOT NULL, `fallbackServerPhoneNumber` TEXT NOT NULL, `allowCleartextTransport` INTEGER NOT NULL, `configManifestUrl` TEXT NOT NULL, `updateManifestUrl` TEXT NOT NULL, `autoUpdateEnabled` INTEGER NOT NULL, `setupCompleted` INTEGER NOT NULL, PRIMARY KEY(`id`));
